#!/usr/bin/env node
'use strict'

/**
 * Generates the standalone app's HTML pages from the server UI.
 *
 * Both share one UI — see the `hasLocalExporter()` seam in
 * `src/server/public/app.js`. Rather than hand-maintain a second copy of ~1900
 * lines of markup, the webapp entries are derived at build time: only the asset
 * paths change, plus one script tag publishing `window.LiaExporter`.
 *
 * Generated files are not committed; `webapp:dev` and `webapp:build` rebuild
 * them.
 */

const fs = require('fs')
const path = require('path')

const PUBLIC = path.join(__dirname, '..', 'src', 'server', 'public')
const GENERATED = path.join(__dirname, '..', 'src', 'webapp', 'generated')

/** Loads window.LiaExporter; must run before the page scripts that check it. */
const EXPORTER_SCRIPT = [
  '    <!-- Publishes window.LiaExporter, which switches the UI to exporting in',
  '         this tab instead of posting to the export service. Loads first. -->',
  '    <script type="module" src="../main.ts"></script>',
].join('\n')

/**
 * Per-page rewrites. Paths are relative to src/webapp/generated/, where the
 * generated files live, so shared assets point back into the server's public
 * directory.
 */
const SHARED_REWRITES = [
  ['href="styles.css"', 'href="../../server/public/styles.css"'],
  ['src="i18n.js"', 'src="../../server/public/i18n.js"'],
  ['src="./assets/icon.svg"', 'src="../../server/public/assets/icon.svg"'],
]

/** Where the web app is published — see .github/workflows/deploy-webapp.yml. */
const SITE_URL = 'https://liascript.github.io/LiaScript-Exporter/'

const DESCRIPTION =
  'Export LiaScript courses to SCORM, IMS, xAPI, PDF, ePub, DOCX and more — ' +
  'directly in your browser, no installation, your course never leaves your device.'

/*
 * Search and link-preview tags. Web app only: they name the public URL, which
 * would be wrong on a local server. The preview image is absolute, as link
 * previews require, so it points at the repository rather than at a file
 * Parcel would rename.
 */
const SEO_TAGS = [
  `    <meta name="description" content="${DESCRIPTION}" />`,
  `    <link rel="canonical" href="${SITE_URL}" />`,
  '    <meta property="og:type" content="website" />',
  '    <meta property="og:site_name" content="LiaScript" />',
  '    <meta property="og:title" content="LiaScript Exporter" />',
  `    <meta property="og:description" content="${DESCRIPTION}" />`,
  `    <meta property="og:url" content="${SITE_URL}" />`,
  '    <meta property="og:image" content="https://raw.githubusercontent.com/LiaScript/LiaScript-Exporter/master/electron/build/icons/512x512.png" />',
  '    <meta name="twitter:card" content="summary" />',
].join('\n')

const PAGES = [
  {
    file: 'index.html',
    rewrites: [
      ...SHARED_REWRITES,
      [
        '    <title>LiaScript Exporter</title>',
        `    <title>LiaScript Exporter</title>\n${SEO_TAGS}`,
      ],
      [
        '    <script src="app.js"></script>',
        `${EXPORTER_SCRIPT}\n    <script src="../../server/public/app.js"></script>`,
      ],
    ],
  },
  {
    file: 'status.html',
    rewrites: [
      ...SHARED_REWRITES,
      // One page per export job; nothing a search engine should list.
      [
        '    <title>Export Status - LiaScript Exporter</title>',
        '    <title>Export Status - LiaScript Exporter</title>\n    <meta name="robots" content="noindex" />',
      ],
      // status.html has no app.js; the bundle goes before its inline script.
      ['    <script>', `${EXPORTER_SCRIPT}\n    <script>`],
    ],
  },
]

fs.mkdirSync(GENERATED, { recursive: true })

for (const page of PAGES) {
  const source = path.join(PUBLIC, page.file)
  let html = fs.readFileSync(source, 'utf8')

  // Format tiles reference `../assets/…`, above the served root. A browser
  // clamps that to the root so it works on the server by accident, but a
  // bundler resolves it literally and fails.
  html = html.split('"../assets/').join('"../../server/public/assets/')
  // Favicons, which every page links.
  html = html.split('href="./assets/').join('href="../../server/public/assets/')

  for (const [from, to] of page.rewrites) {
    if (!html.includes(from)) {
      console.error(
        `build-webapp-html: could not find ${JSON.stringify(from)} in ${path.relative(process.cwd(), source)}.\n` +
          'The server UI changed shape — update PAGES in this script.',
      )
      process.exit(1)
    }

    html = html.replace(from, to)
  }

  fs.writeFileSync(
    path.join(GENERATED, page.file),
    `<!-- GENERATED by scripts/build-webapp-html.js — edit src/server/public/${page.file} instead. -->\n` +
      html,
  )
}

console.log(
  `webapp html  ${PAGES.map((p) => p.file).join(', ')} generated from src/server/public/`,
)
